message.content:
{
  "description": "The creature is depicted in right-facing profile against a plain light background, standing on four legs. It has the overall body shape, head, fur, and tail of a shaggy goat combined with the domed carapace and joint armor of a tortoise. The fur is long and coarse, brown-gray on the back, neck and sides with a paler cream-white belly and a beard under the chin. A large, high-domed tortoise shell with patterned scutes sits centrally on the back covering the mid-dorsum, and matching segmented bony plates encircle the upper and lower sections of each leg. The head is goat-like with a narrow muzzle, dark nose, and a visible eye, topped with two curved horns, and the rear bears a short tufted furry tail that protrudes from beneath the shell.",
  "parts": [
    {
      "part": "head",
      "looks_like": "goat-like head with elongated muzzle, dark nostril, slightly open mouth showing lower teeth, brown eye with eyelid, and shaggy brown-gray fur with a darker stripe down the nose and lighter fur around the muzzle",
      "where": "at the front end of the body on a thick neck, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "two thick, curved, ridged horns with concentric growth rings, dark brown, tapering to pointed tips and sweeping backward",
      "where": "on top of the head behind the ears"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, triangular ears with visible inner fur and dark interior shading",
      "where": "on the sides of the head just below and behind the horns"
    },
    {
      "part": "mane and beard",
      "looks_like": "long, shaggy, wavy fur forming a thick ruff around the neck and chest and a hanging beard under the chin, colored mixed brown, gray and tan with a cream-white belly",
      "where": "covering the neck, chest, sides, belly and hindquarters of the body"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, columnar legs covered in shaggy fur except where encircled by overlapping bony plates, with visible joints at shoulder/thigh and knee/hock",
      "where": "beneath the body, two forelegs under the chest and two hindlegs under the rear"
    },
    {
      "part": "feet",
      "looks_like": "cloven hooves, dark brown-black, with short fur immediately above the hoof wall and two toes per foot",
      "where": "at the distal ends of all four legs contacting the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, bushy, fur-covered tail with long hair at the tip, same brown-gray as the body fur",
      "where": "at the rear of the body on the left side, protruding from under the back edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "large domed tortoise carapace composed of polygonal scutes with raised keels and concentric growth lines in shades of brown, tan, beige and black, with a serrated lower margin",
      "where": "centered on the dorsal mid-back, extending from behind the shoulders to above the hindquarters"
    },
    {
      "part": "plates",
      "looks_like": "segmented, keeled, overlapping bony scutes matching the shell in color and texture, arranged in bands around the limbs",
      "where": "wrapping around the upper and lower portions of all four legs at the shoulder/thigh and shin levels"
    }
  ],
  "attached_objects": [],
  "animals": [
    "goat",
    "tortoise"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
